    "hy": "Platinum ամիս",
    "kk": "Platinum ай",
    "ky": "Platinum ай",
    "ka": "Platinum თვე",
    "uk": "Platinum місяць",
    "pl": "Platinum miesiąc",
    "ro": "Platinum lună",
    "pt": "Platinum mês",
    "ar": "Platinum شهر",
    "bn": "Platinum মাস",
